private void __p_24_ME(String val) {
    if ( Util.isNumeric(val)){
        _minexecsize = (int)Double.parseDouble(val);
    } else {
        String sstr = val.substring(3, val.length());
        double v = Double.parseDouble(sstr);
        if (v > 0) {
            String a = val.substring(0, 3);
            if (a.equalsIgnoreCase("RLS")) {
                if (_stock == null || _stock.roundLotSize() < 1) {
                    _err_msg = "null stock or 0 round lot size: " + _stock;
                }
                _minexecsize = (int)(_stock.roundLotSize()*v);
            } else if (a.equalsIgnoreCase("ATS")) {
                if (_stock == null || _stock.avgTradeSize() < 1) {
                    _err_msg = "null stock or 0 avg trade size: " + _stock;
                }
                _minexecsize = (int)(_stock.avgTradeSize()*v);
            } else if (a.equalsIgnoreCase("AQS")) {
                if (_stock == null || _stock.medBidSize() < 1 && _stock.medAskSize() < 1) {
                    _err_msg = "null stock or 0 avg quote size: " + _stock;
                }
                _minexecsize = (int)(0.5*(_stock.medBidSize()+_stock.medAskSize())*v);
            } else if (a.equalsIgnoreCase("PCT")) {
                _minexecpct = (double) (v / 100);
            } else {
                _minexecvalue = Double.parseDouble(val.substring(3,val.length()));
                _minexecvalue_ccy = CurrencyType.fetch(val.substring(0, 3));
                if (_minexecvalue_ccy==null) {
                    _err_msg = "currency invalid in tag 24";
                }
            }
        }
    }
}

