private void __p_79(String val) {
    _index_tracker_adaption_str = val;
    //stand alone adaption only takes 1 or 2
    if (_index_tracker_adaption_str.equals("1") ||
        _index_tracker_adaption_str.equalsIgnoreCase("trend")) {
        _adaption_sign = -1;
    } else if (_index_tracker_adaption_str.equals("2") ||
            _index_tracker_adaption_str.equalsIgnoreCase("reverse")){
        _adaption_sign = 1;
    }

    if (_index_tracker_adaption_str.equals("1") ||
        _index_tracker_adaption_str.equalsIgnoreCase("trend") ||
        _index_tracker_adaption_str.equals("5")) {
        _index_tracker_adaption = 1;
    } else if (_index_tracker_adaption_str.equals("2") ||
            _index_tracker_adaption_str.equalsIgnoreCase("reverse") ||
            _index_tracker_adaption_str.equals("6") ||
            _index_tracker_adaption_str.equals("7")) {
        _index_tracker_adaption = 2;
    }
    else if (_index_tracker_adaption_str.equals("3")) {
        _index_tracker_adaption = 3;
    }
    else if (_index_tracker_adaption_str.equals("4")) {
        _index_tracker_adaption = 4;
    }
    else
        _index_tracker_adaption = Integer.parseInt(_index_tracker_adaption_str);
}

private void __p_92(String val) {
    _limit_price_percent_str = val.toUpperCase();
    if (_limit_price_percent_str.length()>0){
        if (_limit_price_percent_str.startsWith("H")){
            _limit_price_as_hard = true;
            _limit_price_percent_str = _limit_price_percent_str.substring(1);
        }
        if (Util.isDigit(_limit_price_percent_str.charAt(0))) {
            _limit_price_percent_str = "C," + _limit_price_percent_str;
        }
        try {
            String[] a = _limit_price_percent_str.split(",");
            if (a.length > 1) {
                if(a[1].length() > 0) _limit_price_percent = Double.valueOf(a[1]);
                if (a.length > 2) {
                    if(a[2].length() > 0) _limit_price_num_ticks = Integer.valueOf(a[2]);

                    if (a.length > 3) {
                        if(a[3].length() > 0) _tag_limit_price_mode = Integer.valueOf(a[3]);
                    }
                }
            }
            // if limit price is better than open, set do open to 0
            if (_limit_price_percent_str.startsWith("O") &&
                ((_limit_price_percent == null && _limit_price_num_ticks != null && _limit_price_num_ticks < 0) ||
                (_limit_price_num_ticks == null && _limit_price_percent != null && _limit_price_percent < 0) ||
                (_limit_price_percent != null && _limit_price_percent < 0 && _limit_price_num_ticks != null &&
                _limit_price_num_ticks < 0))
            ) {
                log.info("limitprice percent:", _limit_price_percent, " | ticks:",
                    _limit_price_num_ticks, " set not do open!");
                _inopen9014 = 0;
            }
        } catch (Exception e) {
            log.info("incorrect limit_price_percent_str: " + _limit_price_percent_str);
            _limit_price_percent_str="";
            _limit_price_percent = null;
            _limit_price_num_ticks = null;
        }
    }
}

