private void __p_2(String val) {
    val = val.trim();
    int n = val.length();
    char u = val.charAt(n-1);
    if (u == 's' || u == 'S') {
        _start_open = Util.toRealDuration(1000L*Integer.parseInt(val.substring(0,n-1)));
        _startstamp_need_conversion = false;
    } else if (u == 'm' || u == 'M') {
        _start_open = Util.toRealDuration(60000L*Integer.parseInt(val.substring(0,n-1)));
        _startstamp_need_conversion = false;
    } else if (u == 'h' || u == 'H') {
