            if (a[2].trim().length() > 0) {
                _coda_min_size_part0 = Integer.parseInt(a[2].trim());
            }
        }
    }
    if (Util.config().coda_min_size_str() != null && Util.config().coda_min_size_str().trim().length() > 0) {
        int min_size = 0;
        int min_size_part = 0;
        String[] ay = Util.config().coda_min_size_str().trim().split(";");
        if (ay.length > 2) {
            String[] flds = ay[0].trim().split("\\s+");
            if (flds.length == 0 || flds.length % 2 == 0) {
                log.info("invalid coda_min_size_str: " + Util.config().coda_min_size_str());
            } else {
                try {
                    int ncaps = flds.length / 2;
                    int nsteps = ncaps + 1;
                    int[] sizes  = new int[nsteps];
                    double[] caps = new double[nsteps];
                    int i;
                    for (i = 0; i < ncaps; ++i) {
                        sizes[i]  = Integer.parseInt(flds[i * 2]);
                        String s = flds[i * 2 + 1];
                        if (s.endsWith("B")) {
                            caps[i] = 1e9 * Double.parseDouble(s.substring(0, s.length() - 1));
                        } else {
                            caps[i] = Double.parseDouble(s);
                        }
                    }
                    sizes[i] = Integer.parseInt(flds[i * 2]);
                    double highprice = Double.parseDouble(ay[1]);
                    min_size_part = Integer.parseInt(ay[2]);
                    if (highprice > 0 && _stock.prevClose() > highprice) {
                        min_size = sizes[0];
                    } else {
                        if (nsteps == 1) {
                            min_size = sizes[0];
                        } else {
                            for (i = 0; i < ncaps; ++i) {
                                if (_stock.marketCapUSD()*1e6 < caps[i]) {
                                    break;
                                }
                            }
                            min_size = sizes[i];
                            log.info("coda_min_size: ", min_size, _stock.id(), _stock.marketCapUSD(), Util.config().coda_min_size_str());
                        }
                    }
                } catch (Exception e) {
                    log.error(e);
                    log.info("invalid coda_min_size_str formats: " + Util.config().coda_min_size_str());
                }
            }
        }
        _coda_min_size = Math.max(_coda_min_size0, min_size);
        _coda_min_size_part = Math.max(_coda_min_size_part0, min_size_part);
    }
}

